function settings(){return header("Instellingen")+'<div class="settings-stack">'+card("Applicatie",'<div id="update-panel">'+updatePanel()+'</div>')+card("Gegevens op dit apparaat",'<p id="storage-detail">Je trainingen worden op dit apparaat opgeslagen (IndexedDB).</p><div class="action-menu">'+menuAction("download","Back-up exporteren","export")+menuAction("upload","Back-up importeren","backup-select",db.active?"disabled":"")+menuAction("download","Gegevens vóór laatste herstel exporteren","backup-previous")+menuAction("settings","Blijvende browseropslag aanvragen","persist-storage")+'</div><input type="file" id="backup-file" accept=".json,application/json" hidden><p id="backup-status" role="status" class="form-hint">'+(db.active?"Rond de actieve training eerst af.":"Importeren vervangt de lokale gegevens.")+'</p><p class="muted">Gebruik fictieve testgegevens. Maak regelmatig een back-up: bij het wissen van websitegegevens kan je historie verloren gaan. Er worden geen trainingsgegevens naar Supabase verzonden.</p>')+card("Account en integraties",'<p>Lokale testversie. Apple-login en synchronisatie zijn nog niet aangesloten.</p><small>Uitgesteld: Apple-login · Cloudsynchronisatie · BridgeAthletic-import · Apple Health · AI</small>')+'</div>'}
function showDialog(title,body,handler){let d=$("dialog");d.setAttribute("aria-labelledby","dialog-title");d.innerHTML='<form id="dialog-form" class="compact-form"><div class="dialog-heading"><h2 id="dialog-title">'+h(title)+'</h2>'+b(uiIcon("close"),"dialog-close","dialog-x",'aria-label="Sluiten"')+'</div><div class="dialog-fields">'+body+'</div><div class="dialog-actions">'+b("Annuleren","dialog-close","dialog-cancel")+'<button type="submit" class="primary">Bevestigen</button></div></form>';if(!d.open)d.showModal();updateAccessory();$("dialog-form").onsubmit=ev=>{ev.preventDefault();const form=new FormData(ev.currentTarget);d.close();handler(form)}}
