function openEvent(e){if(!e)return;if(e.type==="fitness"){previewProgram=page==="programView"?opened:null;previewBack=page==="agenda"||page==="today"||page==="programView"?page:"schemas";opened={eventId:e.id,workoutId:e.workoutId};go("preview");return}showDialog(e.name,'<p class="form-hint">Gepland · '+fmt(e.date)+'</p>'+fieldPair(field("Datum","date",e.date,"date","required"),field("Werkelijke duur","minutes",e.minutes,"number","required min=1 max=1440"))+rpeField(),f=>{if(db.history.some(x=>x.eventId===e.id))return;db.history.push({id:id(),eventId:e.id,type:e.type,name:e.name,date:f.get("date"),minutes:Number(f.get("minutes")),rpe:validRpe(f.get("rpe"))?Number(f.get("rpe")):null,finished:Date.now()});selected=f.get("date");week=monday(selected);save();go(page==="agenda"||selected!==dateToday()?"agenda":"today")})}
function newProgram(){if(!db.workouts.some(w=>!w.archived)){alert("Maak eerst een workout aan.");newDraft();return}showDialog("Nieuw programma",field("Naam","name","","text","required maxlength=100")+fieldPair(field("Startdatum","start",dateToday(),"date","required"),field("Duur","weeks","6","number","required min=1 max=52")),f=>{let p={id:id(),name:String(f.get("name")).trim(),start:f.get("start"),weeks:Number(f.get("weeks")),entries:[],overrides:{}};if(!p.name)return;db.programs.push(p);save();opened=p.id;go("programView");addProgramWorkout()})}
function addProgramWorkout(){const p=program(opened);if(!p)return;if(!db.workouts.some(w=>!w.archived)){alert("Maak eerst een actieve workout aan.");return}showDialog("Workout toevoegen",selectField("Workout","workoutId",workoutOptions())+weekdayPicker(),f=>{const days=f.getAll("days").map(Number),wid=f.get("workoutId");if(!days.length||!workout(wid)||workout(wid).archived){alert("Kies een workout en minimaal één weekdag.");return}if(p.entries.some(x=>x.workoutId===wid)){alert("Deze workout is al opgenomen in dit programma.");return}p.entries.push({workoutId:wid,days});reconcileProgram(db,p,dateToday(),id,wid);save();render()})}
function weekTargets(wid){let p=program(opened),w=workout(wid);if(!p||!w)return;const ov=p.overrides[wid]||{};showDialog("Richtwaarden per week",Array.from({length:p.weeks},(_,i)=>'<div class="row between"><h3>Week '+(i+1)+'</h3>'+(i<p.weeks-1?b("Kopieer naar volgende","week-copy","quiet",'data-i="'+i+'" data-count="'+w.exercises.length+'"'):"")+'</div>'+w.exercises.map((e,j)=>'<small>'+h(e.name)+'</small><div class="row"><div class="grow">'+field(e.mode==="time"?"Tijd (sec)":"Reps","r"+i+"_"+j,ov[i+1]?.[e.id]?.reps??e.reps,"text","required")+'</div>'+(!e.bodyweight?'<div class="grow">'+field("Gewicht","k"+i+"_"+j,ov[i+1]?.[e.id]?.kg??e.kg,"number","min=0 max=2000 step=any")+'</div>':"")+'</div>').join("")).join(""),f=>{let next={};for(let i=0;i<p.weeks;i++){next[i+1]={};for(let j=0;j<w.exercises.length;j++){let e=w.exercises[j],reps=f.get("r"+i+"_"+j),kg=f.get("k"+i+"_"+j)??"";if(!repRange(reps)||(!e.bodyweight&&kg!==""&&!validKg(kg))){alert("Ongeldige richtwaarden.");return}next[i+1][e.id]={reps,kg}}}p.overrides[wid]=next;save();render()})}
function historyEdit(){const x=db.history.find(s=>s.id===detailId);if(!x)return;historyDraft=copy(x);historyOrigin="historyDetail";go("historyEditor")}
function manualHistory(){const origin=page;showDialog("Training registreren",selectField("Type","type",Object.entries(types).map(([k,v])=>'<option value="'+k+'">'+h(v)+'</option>').join(""))+field("Naam (optioneel)","name","","text","maxlength=100")+fieldPair(field("Datum","date",origin==="agenda"?selected:dateToday(),"date","required"),field("Duur","minutes","60","number","required min=1 max=1440")),f=>{const type=f.get("type"),date=f.get("date"),minutes=Number(f.get("minutes"));if(!validDate(date)||!Number.isInteger(minutes)||minutes<1||minutes>1440){alert("Controleer datum en duur.");return}historyDraft={id:id(),type,name:String(f.get("name")).trim()||types[type],date,minutes,rpe:null,note:"",finished:Date.now(),...(type==="fitness"?{exercises:[]}: {})};historyOrigin=origin;go("historyEditor")})}
function syncHistory(){if(page!=="historyEditor"||!historyDraft)return;const form=$("history-form");if(!form)return;const x=historyDraft;x.name=form.elements.name.value;x.date=form.elements.date.value;x.minutes=Number(form.elements.minutes.value);x.rpe=form.elements.rpe.value===""?null:Number(form.elements.rpe.value);x.note=form.elements.note.value;for(const [i,e] of (x.exercises||[]).entries()){for(const [j,s] of e.logs.entries()){const suffix=i+"_"+j;s.reps=form.elements["hr"+suffix].value;s.kg=e.bodyweight?"":form.elements["k"+suffix].value.replace(",",".");s.done=form.elements["hd"+suffix].checked;if(s.done)e.skipped=false}}}
function historyExerciseCard(e,i){const members=circuitMembers(historyDraft.exercises,e);return '<section class="card history-edit-card"><div class="head row between"><span>Oefening '+(i+1)+'/'+historyDraft.exercises.length+(members.length>1?' · '+(members.length===2?'Superset':members.length===3?'Triset':'Circuit'):'')+'</span>'+b(uiIcon("more"),"he-options","quiet menu-icon",'data-i="'+i+'" aria-label="Oefening aanpassen"')+'</div><div class="inside"><h2>'+h(e.name)+'</h2><small>'+(e.skipped?"Overgeslagen":e.mode==="time"?"Tijd in seconden":e.ea?"Each (ea)":e.equipment==="Dumbbell"?"kg per dumbbell":"")+'</small></div>'+e.logs.map((s,j)=>{const suffix=i+"_"+j;return '<div class="history-edit-set '+(e.bodyweight?"bodyweight ":"")+(s.warmup?"warmup":"")+'"><span class="set-number">'+setLabel(e,s,j)+'</span><div class="field"><input name="hr'+suffix+'" aria-label="Set '+(j+1)+' '+(e.mode==="time"?"seconden":"reps")+'" type="text" inputmode="numeric" value="'+h(s.reps)+'"><span class="unit">'+(e.mode==="time"?"sec":"reps")+'</span></div>'+(!e.bodyweight?'<div class="field"><input name="k'+suffix+'" aria-label="Set '+(j+1)+' gewicht" type="text" inputmode="decimal" value="'+h(s.kg)+'"><span class="unit">kg</span></div>':"")+'<label class="he-done"><input type="checkbox" name="hd'+suffix+'" '+(s.done?"checked":"")+' aria-label="Set '+(j+1)+' voltooid"></label>'+b(uiIcon("minus"),"he-remove-set","quiet danger he-remove",'data-i="'+i+'" data-n="'+j+'" aria-label="Set '+(j+1)+' verwijderen"')+'</div>'}).join("")+'<div class="row wrap inside">'+b("+ Set","he-add-set","quiet",'data-i="'+i+'"')+b("+ Warm-up","he-warmup","quiet",'data-i="'+i+'"')+'</div></section>'}
function historyEditor(){const x=historyDraft;if(!x)return history();return header("Training bewerken","historyEditorCancel")+'<form id="history-form" data-form="history" class="stack"><div class="manage-card">'+field("Naam","name",x.name,"text","required maxlength=100")+fieldPair(field("Datum","date",x.date,"date","required"),field("Duur","minutes",x.minutes,"number","required min=1 max=1440"))+rpeField(x.rpe??"")+'<label for="note">Trainingsnotities</label><textarea id="note" name="note" rows="2" maxlength="10000">'+h(x.note||"")+'</textarea></div>'+(x.type==="fitness"?'<p class="form-hint">Vink uitsluitend werkelijk uitgevoerde sets af. Vul de daadwerkelijke reps/tijd en het gewicht in.</p>'+x.exercises.map(historyExerciseCard).join("")+b("+ Oefening toevoegen","he-add","outline full"):"")+'<button class="primary" type="submit">Wijzigingen opslaan</button>'+b("Annuleren","he-cancel","quiet full")+'</form>'}
