document.addEventListener("submit",ev=>{if(ev.target.dataset.form==="history"){ev.preventDefault();syncHistory();if(!validateHistoryDraft(historyDraft)){alert("Controleer naam, datum, duur en werkelijke waarden; vink minimaal één uitgevoerde set af.");return}const x=copy(historyDraft);x.name=x.name.trim();for(const e of x.exercises||[]){for(const s of e.logs){s.reps=String(s.reps).replace(",",".");s.kg=String(s.kg).replace(",",".")}}const idx=db.history.findIndex(h=>h.id===x.id);if(idx<0)db.history.push(x);else db.history[idx]=x;detailId=x.id;if(idx<0)historyBack=historyOrigin;historyDraft=null;save();go("historyDetail");return}if(ev.target.dataset.form!=="builder")return;ev.preventDefault();syncBuilder();if(!draft.name.trim()||!draft.exercises.length||!validSupersets(draft.exercises)||draft.exercises.some(e=>!repRange(e.reps)||!validSetTargets(e)||!Number.isInteger(e.warmupCount)||e.warmupCount<0||e.warmupCount>10||(e.warmupCount>0&&(!repRange(e.warmupReps)||(e.warmupKg!==""&&!validKg(e.warmupKg))))||!Number.isInteger(e.sets)||e.sets<1||e.sets>30||!Number.isInteger(e.rest)||e.rest<0||e.rest>900||(!e.bodyweight&&e.kg!==""&&!validKg(e.kg)))){alert("Controleer naam, sets, reps, gewicht en trainingsblokken (2–6 oefeningen met evenveel werksets; geen dropsets in circuit).");return}const idx=db.workouts.findIndex(w=>w.id===draft.id);if(idx<0)db.workouts.push(copy(draft));else db.workouts[idx]=copy(draft);opened={workoutId:draft.id};save();draft=null;go("preview")});
document.addEventListener("input",ev=>{const t=ev.target;if(page==="builder"&&t.closest(".builder-fold")){const fold=t.closest(".builder-fold"),i=Number(fold.dataset.builderIndex),f=$("builder-form"),summary=fold.querySelector("[data-builder-summary]");if(summary&&f)summary.textContent=builderSummary({sets:f.elements["sets"+i].value,reps:f.elements["reps"+i].value,kg:f.elements["kg"+i]?.value,bodyweight:f.elements["bw"+i].checked,mode:f.elements["mode"+i]?.value,rest:f.elements["rest"+i].value})}if(page==="training"&&t.dataset.field){let s=db.active.exercises[Number(t.dataset.ex)].logs[Number(t.dataset.set)];s[t.dataset.field]=t.value.replace(",",".");save();updateAccessory()}if(page==="schemas"&&t.id==="workout-search"){workoutSearch=t.value;$("workout-results").innerHTML=workoutResults()}if(page==="libraryView"&&t.id==="search"){filters.q=t.value;updateFilters()}});
