let swipeStart=null,dragStart=null,suppressClickUntil=0;
document.addEventListener("pointerdown",ev=>{if(!ev.isPrimary)return;const handle=ev.target.closest(".drag-handle");if(page==="builder"&&handle){dragStart={id:ev.pointerId,from:Number(handle.dataset.i),to:Number(handle.dataset.i),y:ev.clientY};handle.setPointerCapture?.(ev.pointerId);ev.preventDefault();return}if(page==="agenda"&&ev.target.closest(".cal-grid,.cal-week-list"))swipeStart={id:ev.pointerId,x:ev.clientX,y:ev.clientY}});
document.addEventListener("pointermove",ev=>{if(!dragStart||ev.pointerId!==dragStart.id)return;const cards=[...document.querySelectorAll(".builder-card")];const target=cards.find(c=>{const r=c.getBoundingClientRect();return ev.clientY>=r.top&&ev.clientY<=r.bottom});if(target)dragStart.to=Number(target.dataset.order);cards.forEach(c=>c.classList.toggle("drag-target",Number(c.dataset.order)===dragStart.to));if(ev.clientY<75)window.scrollBy(0,-12);else if(ev.clientY>window.innerHeight-85)window.scrollBy(0,12)});
document.addEventListener("pointerup",ev=>{if(dragStart&&ev.pointerId===dragStart.id){const d=dragStart;dragStart=null;document.querySelectorAll(".drag-target").forEach(c=>c.classList.remove("drag-target"));if(Math.abs(ev.clientY-d.y)>12&&d.from!==d.to){syncBuilder();moveItem(draft.exercises,d.from,d.to);suppressClickUntil=Date.now()+350;render()}return}if(!swipeStart||ev.pointerId!==swipeStart.id)return;const s=swipeStart;swipeStart=null;const dx=ev.clientX-s.x,dy=ev.clientY-s.y;if(page==="agenda"&&Math.abs(dx)>65&&Math.abs(dx)>1.6*Math.abs(dy)){const delta=dx<0?1:-1;selected=calendarMode==="month"?monthShift(selected,delta):dateAdd(selected,delta*7);week=monday(selected);suppressClickUntil=Date.now()+350;render()}});
document.addEventListener("pointercancel",()=>{swipeStart=null;dragStart=null;document.querySelectorAll(".drag-target").forEach(c=>c.classList.remove("drag-target"))});
document.addEventListener("click",ev=>{if(Date.now()<suppressClickUntil){ev.stopImmediatePropagation();ev.preventDefault()}},true);

